{"path": "robot_name.py", "content": "import random
import string


class Robot:
    """A robot with a unique, randomly generated name."""

    # Names currently held by existing robots, shared across all instances.
    _used_names = set()
    _MAX_NAMES = 26 * 26 * 1000

    def __init__(self):
        self.name = self._generate_name()

    @classmethod
    def _generate_name(cls):
        if len(cls._used_names) >= cls._MAX_NAMES:
            raise RuntimeError("All possible robot names are in use")
        while True:
            name = "".join(random.choices(string.ascii_uppercase, k=2)) + "".join(
                random.choices(string.digits, k=3)
            )
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name

    def reset(self):
        """Wipe the robot's name and assign a new, unique one."""
        old_name = self.name
        # Generate the new name before releasing the old one so the robot
        # never gets its previous name back.
        self.name = self._generate_name()
        Robot._used_names.discard(old_name)
